INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_289', 'mbe', '289', '170', 'MBE-1978-83-part1', '', '141', 'Reggie offered Harriet $200 for a 30-day option to buy Harriet''s land, Grandvale, for $10,000. As Harriet knew, Reggie, if granted the option, intended to resell Grandvale at a profit. Harriet declined, believing that she could find a desirable purchaser herself. Reggie thereupon said to Harriet, "Make me a written 30-day offer, revocable at your pleasure, to sell me Grandvale at a sale price of $10,000, and tomorrow I will pay you $200 for so doing. " Harriet agreed and gave Reggie the following document: For 30 days I offer my land known as Grandvale to Reggie for $10,000, this offer to be revocable at my pleasure at any time before acceptance. [Signed] Harriet Later that day Harriet''s neighbor, Norma, said to Harriet, "I know someone who would probably buy Grandvale for $15,000." Harriet asked, "Who?" and Norma replied, "My cousin Portia." Harriet thanked Norma. Several hours later, Norma telephoned Harriet and said, "Of course, if you sell to Portia I will expect the usual 5 per cent brokerage fee for finding a buyer." Harriet made no reply. The next day Harriet telephoned Reggie, declared that her written offer to him was revoked, and demanded payment of $200. Reggie refused to pay. Harriet subsequently sold Grandvale to Portia for $15,000 but refused to pay Norma anything.', 'Which of the following would best describe the basis of any duty or duties created by Reggie''s oral promise and Harriet''s writing?', 'Firm option', 'Precontractual liability by promissory estoppel', 'Unilateral contract', 'Quasi-contractual liability', 'C', 'A unilateral contract is a contract in which “performance is based on the wish, will, or pleasure of one of the parties.” Cook v. Coldwell Banker, 967 S.W.2d 654, 657 (Mo.App. E.D.1998).', 'mbe_2629', 0, '141'),
('mbe_290', 'mbe', '290', '170', 'MBE-1978-83-part1', '', '142', 'Reggie offered Harriet $200 for a 30-day option to buy Harriet''s land, Grandvale, for $10,000. As Harriet knew, Reggie, if granted the option, intended to resell Grandvale at a profit. Harriet declined, believing that she could find a desirable purchaser herself. Reggie thereupon said to Harriet, "Make me a written 30-day offer, revocable at your pleasure, to sell me Grandvale at a sale price of $10,000, and tomorrow I will pay you $200 for so doing. " Harriet agreed and gave Reggie the following document: For 30 days I offer my land known as Grandvale to Reggie for $10,000, this offer to be revocable at my pleasure at any time before acceptance. [Signed] Harriet Later that day Harriet''s neighbor, Norma, said to Harriet, "I know someone who would probably buy Grandvale for $15,000." Harriet asked, "Who?" and Norma replied, "My cousin Portia." Harriet thanked Norma. Several hours later, Norma telephoned Harriet and said, "Of course, if you sell to Portia I will expect the usual 5 per cent brokerage fee for finding a buyer." Harriet made no reply. The next day Harriet telephoned Reggie, declared that her written offer to him was revoked, and demanded payment of $200. Reggie refused to pay. Harriet subsequently sold Grandvale to Portia for $15,000 but refused to pay Norma anything.', 'In a lawsuit by Norma against Harriet to recover $750 as a brokerage fee, which of the following arguments would effectively support Harriet''s position? I. Harriet made no promise to pay such a fee. II. Even if it be assumed arguendo that Harriet made a promise to pay such a fee, there was no bargained-for consideration for that promise. III. There was no effective offer and acceptance between Norma and Harriet.', 'I and II only', 'I and III only', 'II and III only', 'I, II, and III', 'D', 'a party must prove the existence of a contract by showing that: “(1) there was a meeting of the minds; (2) there was an offer and acceptance; (3) there was consideration; and, (4) there was certainty in the terms of the agreement.” See id. at *3 (citation omitted).', 'mbe_2630', 0, '142'),
('mbe_301', 'mbe', '301', '175', 'MBE-1978-83-part1', '', '153', '', 'Realco Realtors acquired a large tract of land upon which Realco developed a mobile home subdivision. The tract was divided into 60 lots, appropriate utilities were installed, and a plat of the entire tract, including a Declaration of Restrictions, was properly drawn and recorded. The Declaration of Restrictions included the following: "3. Ownership and/or occupancy are restricted to persons 21 years of age or over; one family per lot." As the separate lots were sold, the deed to each lot included the following provision: "As shown on recorded plat [properly identified by page and plat book reference] and subject to the restrictions therein contained." One of the lots was purchased by Dawson, who now resides in a mobile home on the lot together with his wife and two children, aged 11 and 13. Other lot owners in the subdivision brought action against Dawson to enjoin further occupancy by the children under 21 years of age. If judgment Is for Dawson, the issue that most likely will determine the case will be whether', 'the mobile home is treated as personalty or realty', 'the restriction constitutes an unlawful restraint on alienation', 'enforcement of the restriction is considered a violation of the equal protection clause of the Fourteenth Amendment to the United States Constitution', 'the terms of the restriction are expressly repeated verbatim In Dawson''s deed', 'C', 'The Equal Protection Clause is essentially a requirement that all persons similarly situated should be treated alike.', 'mbe_2631', 0, '153'),
('mbe_307', 'mbe', '307', '178', 'MBE-1978-83-part1', '', '159', 'The Federal Automobile Safety Act establishes certain safety and performance standards for all automobiles manufactured in the United States. The Act creates a five-member "Automobile Commission" to investigate automobile safety, to make recommendations to Congress for new laws, to make further rules establishing safety and performance standards, and to prosecute violations of the act. The chairman is appointed by the President, two members are selected by the President pro tempore of the Senate, and two by the Speaker of the House of Representatives. Minicar, Inc., a minor United States car manufacturer. seeks to enjoin enforcement of the Commission''s rules.', 'The best argument that Minicar can make is that', 'legislative power may not be delegated by Congress to an agency in the absence of clear guidelines', 'the commerce power does not extend to the manufacture of automobiles not used in interstate commerce', 'Minicar Is denied due process of law because it is not represented on the Commission', 'the Commission lacks authority to enforce its standards because not all of its members were appointed by the President', 'D', 'The Constitution gave the power of appointing federal officers, including ambassadors, judges, and other officials, to the President along with the advice and consent of the Senate. The President nominates the officials and the nominations move to the Senate for the confirmation process.', 'mbe_2632', 0, '159'),
('mbe_308', 'mbe', '308', '178', 'MBE-1978-83-part1', '', '160', 'The Federal Automobile Safety Act establishes certain safety and performance standards for all automobiles manufactured in the United States. The Act creates a five-member "Automobile Commission" to investigate automobile safety, to make recommendations to Congress for new laws, to make further rules establishing safety and performance standards, and to prosecute violations of the act. The chairman is appointed by the President, two members are selected by the President pro tempore of the Senate, and two by the Speaker of the House of Representatives. Minicar, Inc., a minor United States car manufacturer. seeks to enjoin enforcement of the Commission''s rules.', 'The appropriate decision for the court is to', 'allow the Commission to continue investigating automobile safety and making recommendations to Congress', 'allow the Commission to prosecute violations of the act but not allow it to issue rules', 'forbid the Commission to take any action under the act', 'order that all members of the Commission be appointed by the President by and with the advice and consent of the Senate', 'A', 'Under the Appointments Clause, which prescribes the exclusive means of appointing Officers of the United States, only the President, a court of law, or a head of department can do so, and only the President, with the advice and consent of the Senate, can appoint a principal officer, but Congress, instead of relying on that method, may authorize the President alone, a court, or a department head to appoint an inferior officer.', 'mbe_2633', 0, '160'),
('mbe_326', 'mbe', '326', '188', 'MBE-1978-83-part1', '', '178', '', 'In 1963 Hobson was appointed to a tribunal established pursuant to a congressional act. The tribunal''s duties were to review claims made by veterans and to make recommendations to the Veterans Administration on their merits. Congress later abolished the tribunal and established a different format for review of such claims. Hobson was offered a federal administrative position in the same bureau at a lesser salary. He thereupon sued the government on the ground that Congress may not remove a federal judge from office during good behavior nor diminish his compensation during continuance in office. Government attorneys filed a motion to dismiss the action. The court should', 'deny the motion because of the independence of the federal judiciary constitutionally guaranteed by Article III', 'deny the motion, because Hobson has established a property right to his federal employment on the tribunal', 'grant the motion, because Hobson lacked standing to raise the question', 'grant the motion, because Hobson was not a judge under Article III and is not entitled to life tenure', 'D', 'Article III states that these judges “hold their office during good behavior,” which means they have a lifetime appointment, except under very limited circumstances. Article III judges can be removed from office only through impeachment by the House of Representatives and conviction by the Senate.', 'mbe_2634', 0, '178'),
('mbe_333', 'mbe', '333', '194', 'MBE-1978-83-part1', '', '185', 'An act of Congress provides that "no federal court shall order the implementation of a public school desegregation plan that would require the transportation of any student to a school ocher than the school closest or next closest to his place of residence."', 'Which of the following is the strongest argument for the constitutionality of the act?', 'The Fourteenth Amendment authorizes Congress to define governmental conduct which violates the equal protection clause.', 'Under Article III, Congress may restrict the jurisdiction of the federal courts.', 'Transportation of students is subject to regulation by Congress because commerce is involved.', 'Congress provides partial support for public education and is therefore entitled to establish conditions upon the expenditure of federal grants.', 'B', 'Unlike its original jurisdiction, the appellate jurisdiction of the Supreme Court is subject to “exceptions and regulations” prescribed by Congress, and the jurisdiction of the inferior federal courts is subject to congressional prescription. Additionally, Congress has power to regulate modes and practices of proceeding on the part of the inferior federal courts. Whether there are limitations to the exercise of these congressional powers, and what the limitations may be, are matters that have vexed scholarly and judicial interpretation over the years, inasmuch as congressional displeasure with judicial decisions has sometimes led to successful efforts to “curb” the courts and more frequently to proposed but unsuccessful curbs.', 'mbe_2635', 0, '185'),
('mbe_334', 'mbe', '334', '194', 'MBE-1978-83-part1', '', '186', 'An act of Congress provides that "no federal court shall order the implementation of a public school desegregation plan that would require the transportation of any student to a school ocher than the school closest or next closest to his place of residence."', 'Which of the following is the strongest argument against the constitutionality of the act?', 'This statute unduly burdens interstate commerce.', 'Congress cannot limit the authority of federal courts to hear and decide cases properly presented for decision.', 'The privileges and immunities clause of the Fourteenth Amendment prohibits Congress from limiting the forms of relief afforded by federal courts.', 'The courts, not Congress, have the primary responsibility for defining the minimum requirements of the equal protection clause of the Fourteenth Amendment.', 'D', 'Application of the Privileges and Immunities Clause to a particular instance of discrimination against out-of-state residents entails a two-step inquiry. As an initial matter, the court must decide whether the ordinance burdens one of those privileges and immunities protected by the Clause. Baldwin v. Montana Fish and Game Comm''n, 436 U.S. 371, 383, 98 S.Ct. 1852, 1860, 56 L.Ed.2d 354 (1978). Not all forms of discrimination against citizens of other States are constitutionally suspect.
“Some distinctions between residents and nonresidents merely reflect the fact that this is a Nation composed of individual States, and are permitted; other distinctions are prohibited because they hinder the formation, the purpose, or the development of a single Union of those States. Only with respect to those ‘privileges'' and ‘immunities'' bearing upon the vitality of the Nation as a single entity must the State treat all citizens, resident and nonresident, equally.” Ibid.
As a threshold matter, then, we must determine whether an out-of-state resident''s **1028 interest in employment on public works contracts in another State is sufficiently “fundamental” to the promotion of interstate harmony so as to “fall within the purview of the Privileges and Immunities Clause.” Id., at 388, 98 S.Ct., at 1862. See also *219 Canadian Northern Ry. Co. v. Eggen, 252 U.S. 553, 560, 40 S.Ct. 402, 403, 64 L.Ed. 713 (1920); Blake v. McClung, 172 U.S. 239, 248, 19 S.Ct. 165, 169, 43 L.Ed. 432 (1898).', 'mbe_2636', 0, '186'),
('mbe_336', 'mbe', '336', '196', 'MBE-1978-83-part1', '', '188', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Which of the following accurately states the legal effect of the covenant not to assign the contract?', 'The covenant made the assignment to Finance Company ineffective.', 'The covenant had no legal effect.', 'Stretch''s assignment was a breach of its contract with Sartorial but was nevertheless effective to transfer to Finance Company Stretch''s rights against Sartorial.', 'By normal interpretation, a covenant against assignment in a sale-of-goods agreement applies only to the buyer, not the seller.', 'C', 'Anti-assignment clauses, such as this one, are routinely enforced. Conoco, Inc. v. Republic Ins. Co., 819 F.2d 120, 123 (5th Cir.1987); Tex. Farmers Ins. Co. v. Gerdes, 880 S.W.2d 215, 218 (Tex.App.-Fort Worth 1994, writ denied). These clauses are enforceable unless rendered ineffective by an applicable statute, estoppel, waiver, or some other aspect of contract law. Johnson v. Structured Asset Servs., LLC, 148 S.W.3d 711, 721 (Tex.App.-Dallas 2004, no pet.); see Tex. Dev. Co. v. Exxon Mobil Corp., 119 S.W.3d 875, 880 (Tex.App.-Eastland 2003, no pet.).11 “In the absence of a successful attack upon an anti-assignment clause, a party is entitled to have the trial court enforce it.” Johnson, 148 S.W.3d at 721 (citing Tex. Pac. Indem. Co. v. Atl. Richfield Co., 846 S.W.2d 580, 583 (Tex.App.-Houston [14th Dist.] 1993, writ denied)).', 'mbe_2637', 0, '188'),
('mbe_337', 'mbe', '337', '196', 'MBE-1978-83-part1', '', '189', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Assume for this question only that the assignment from Stretch to Finance Company was effective, and that Sartorial was unaware of the assignment when it paid Stretch the $5,000. Which of the following is correct?', 'Sartorial is liable to Finance Company for $5,000.', 'Stretch is liable to Finance Company for $5,000.', 'Sartorial and Stretch are each liable to Finance Company for $2,500.', 'Neither Sartorial nor Stretch is liable to Finance Company for any amount.', 'B', 'A covenant against the assignment of a lease without the owner''s consent applies to voluntary assignments and does not include transfers or assignments by operation of law, such as transfers in bankruptcy, execution sales, receiver''s sales, and other transfers in the interests of creditors or lienholders.', 'mbe_2638', 0, '189'),
('mbe_338', 'mbe', '338', '196', 'MBE-1978-83-part1', '', '190', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Assume for this question only that the assignment from Stretch to Finance Company was effective, and that Virginia Wear and Son, Inc., did not become aware of the original agreement between Sartorial and Stretch until after Stretch''s acceptance of the $5,000 payment from Sartorial. Which of the following, if any, is (are) correct? I. Virginia Wear and Son, Inc., was an incidental beneficiary of the Sartorial-Stretch agreement. II. Virginia Wear and Son, Inc., has a prior right to Sartorial''s $5,000 payment as against either Stretch or Finance Company.', 'I only', 'II only', 'Both I and I', 'Neither I nor II', 'D', 'An incidental beneficiary is one “who will be benefited by performance of a promise but who is neither a promisee nor an intended beneficiary.” Only donee and creditor beneficiaries have enforceable rights under a contract.', 'mbe_2639', 0, '190'),
('mbe_339', 'mbe', '339', '196', 'MBE-1978-83-part1', '', '191', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Assume for this question only that, two weeks after making the $5,000 payment to Stretch, Sartorial by written notice to Stretch terminated the agreement for purchase of the elasticized fabric because market conditions had in fact forced Sartorial out of the clothing manufacture business. In an immediate suit by Finance Company against Sartorial for total breach, which of the following would be useful in Sartorial''s defense?', 'Stretch''s rights under its agreement with Sartorial were personal and therefore nonassignable.', 'Stretch''s "assignment of the contract" to Finance Company to secure a loan would normally be interpreted as a delegation of Stretch''s duties under the contract as well as an assignment of its rights; and its duties, owed to Sartorial, were personal and therefore nondelegable.', 'The original contract between Sartorial and Stretch was unenforceable by either party for want of a legally sufficient consideration for Stretch''s promise to supply Sartorial''s requirements of the elasticized fabric.', 'Sartorial ceased in good faith to have any further requirements for elasticized fabric.', 'D', '“Generally, the buyer in a requirements contract governed by UCC § 2-306(1) is required merely to exercise good faith in determining his requirements and the seller assumes the risk of all good faith variations in the buyer''s requirements even to the extent of a determination to liquidate or discontinue the business.” Id. at 1261. “A requirements contract is one in which the purchaser agrees to buy all of its needs of a specified material exclusively from a particular supplier, and the supplier agrees, in turn, to fill all of the purchaser''s needs during the period of the contract.” Id. at 1259. The good faith requirement imposed under the UCC and Indiana Code section 26-1-2-306, prevents requirements contracts from being illusory or too indefinite to be enforced. Id. at 1260.
From time-to-time, there will be variations in the buyer''s requirements. “The essential ingredient of the buyer''s good faith under such circumstances is that he not merely have had second thoughts about the terms of the contract and want to get out of it.” Id. at 1261. On the other hand, if a buyer has a legitimate business reason for eliminating its requirements, instead of a desire to simply avoid the contract, then the buyer is acting in good faith. Id.', 'mbe_2640', 0, '191'),
('mbe_371', 'mbe', '371', '211', 'MBE-1978-83-part5', '', '23', 'In 1971 two police officers in a squad car received a radio message from headquarters to be on the lookout for a large green sedan occupied by two men who had just committed a bank robbery. An hour later they saw a car answering this description traveling down a main boulevard leading out of town. They had the car pull to the side of the road and walked over to the car. One of the officers told the occupants that they were under arrest for bank robbery. Thereupon Dean, the driver, suddenly put the car in gear and drove off. One officer clumb to the car. The other officer pursued in the squad car. Unable to overtake the car and afraid he would lose sight of it in the heavy traffic, the officer fired, first a warning shot and then at the car. He struck Evans, the passenger sitting next to Dean. Dean was caught fives minutes later. Evans died from loss of blood. Dean was taken to the police station. The bank robbers had handed the teller a handwritten note, demanding the money. Dean was required over his protest, to write out the words of the note and have his fingerprints taken. He was then, for the first time, allowed to telephone a lawyer, who thereafter represented him. Dean was charged with murder of Evans.', 'The prosecution, after introducing the robbers'' note to the teller, also offers in evidence Dean''s writing of the words of the note at the request of the police. On appropriate objection, the court should rule this', 'admissible', 'inadmissible, because he was not advised that his handwriting sample could be admitted into evidence against him', 'inadmissible, because he was not advised of his right to refuse to give a handwriting sample', 'inadmissible, because he had not been informed he had a right to have counsel present', 'A', 'Compelling defendant to give handwriting sample did not violate his rights against self-incrimination under either Fifth Amendment or section of State Constitution providing that no person “shall be compelled to give evidence against himself”; handwriting sample is not communication by itself, but rather, is physical characteristic in itself. U.S.C.A. Const.Amend. 5; LSA-Const. Art. 1, § 16.', 'mbe_2641', 0, '23'),
('mbe_372', 'mbe', '372', '211', 'MBE-1978-83-part5', '', '24', 'In 1971 two police officers in a squad car received a radio message from headquarters to be on the lookout for a large green sedan occupied by two men who had just committed a bank robbery. An hour later they saw a car answering this description traveling down a main boulevard leading out of town. They had the car pull to the side of the road and walked over to the car. One of the officers told the occupants that they were under arrest for bank robbery. Thereupon Dean, the driver, suddenly put the car in gear and drove off. One officer clumb to the car. The other officer pursued in the squad car. Unable to overtake the car and afraid he would lose sight of it in the heavy traffic, the officer fired, first a warning shot and then at the car. He struck Evans, the passenger sitting next to Dean. Dean was caught fives minutes later. Evans died from loss of blood. Dean was taken to the police station. The bank robbers had handed the teller a handwritten note, demanding the money. Dean was required over his protest, to write out the words of the note and have his fingerprints taken. He was then, for the first time, allowed to telephone a lawyer, who thereafter represented him. Dean was charged with murder of Evans.', 'Suppose the jury finds Dean guilty of the murder of Evans. Before passing sentence, the judge hears argument by both parties. The prosecutor introduces the criminal record of Dean, showing two prior convictions for felony. Defense counsel admits the correctness of the record. The court imposes the maximum sentence of life imprisonment. On appeal, the appellate court should hold that this sentence', 'violated Dean''s right to due process, in that it deprived him of a fair and unbiased tribunal', 'was in error because the introduction of new evidence after the trial deprived Dean of a fair trial', 'was not in error', 'deprived Dean of the right to confront the witnesses against him', 'C', '“We afford the trial court wide latitude in sentencing and, generally, ‘will reverse a trial court''s sentencing decision only if it is an abuse of the judge''s discretion.’ ” State v. Bluff, 2002 UT 66,¶ 66, 52 P.3d 1210 (citation omitted). Trial courts abuse their discretion “when [they] fail [ ] to consider all legally relevant factors, or if the sentence imposed exceeds the limits prescribed by law.” Id. Generally, a trial court''s sentence “ ‘should be overturned only when it is inherently unfair or clearly excessive.’ ” Id. (citation omitted).', 'mbe_2642', 0, '24'),
('mbe_389', 'mbe', '389', '221', 'MBE-1978-83-part5', '', '41', 'All lawyers practicing in the state of Erewhon must be members of the State Bar Association, by order of the state supreme court. Several state officials serve on the Bar Association''s Board of Bar Governors. The Board of Bar Governors authorizes the payment of dues for two staff members to the Cosmopolitan Club, a private dining club licensed to sell alcohol beverages. The Cosmopolitan Club is frequented by affluent businessmen and professionals and by legislators. It is generally known that the purpose of the membership of the Bar Association staff is to enable them to go where members of the "elite" meet and to lobby for legislation in which the Bar Association is interested. The State Bar Association has numerous committees and subcommittees concerned with family law, real estate law, unauthorized practice, etc., and its recommendations often influence state policy. Some committee meetings are held at the Cosmopolitan Club. The club is known to have rules which restrict membership by race, religion, and sex. Plaintiffs, husband and wife, who are members of the Erewhon Bar Association, petition the Board of Bar Governors to adopt a resolution prohibiting the payment of club dues to and the holding of meetings of the Bar Association or its committees at places which discriminate on the basis of race, religion, or sex. After substantial public discussion, the Board of Bar Governors, by a close vote, fails to pass such a resolution. These events receive extensive coverage in the local newspapers. Plaintiffs bring an action in federal court seeking an injunction against such payments and the holding of meetings in such places as the Cosmopolitan Club.', 'The strongest argument for plaintiffs is', 'private rights to discriminate and associate freely must defer to a public interest against discrimination on the basis of race, religion, or sex', 'the failure of the State Bar Association to pass a resolution forbidding discrimination on the basis of race, religion, or sex constitutes a denial of equal protection', 'the State Bar Association is an agency of the state and its payment of dues to such private clubs promotes discrimination on the basis of race, religion, and sex', 'the State Bar Association''s payment of dues to such private clubs promotes discrimination on the basis of race, religion, and sex', 'C', 'When the government expressly classifies persons on the basis of race or national origin, however, its action is “ ‘immediately suspect.’ ” Johnson v. California, 543 U.S. 499, 125 S.Ct. 1141, 1148, 160 L.Ed.2d 949 (2005) (quoting Shaw v. Reno, 509 U.S. 630, 642, 113 S.Ct. 2816, 125 L.Ed.2d 511 (1993)). A plaintiff in such a lawsuit need not make an extrinsic showing of discriminatory animus or a discriminatory effect to trigger strict scrutiny. “No inquiry into legislative purpose is necessary when the racial classification appears on the face of the statute.”  Shaw, 509 U.S. at 642, 113 S.Ct. 2816. The burden of proof shifts, strict scrutiny applies, and “[u]nder strict scrutiny, the government [defending the constitutionality of the law] has the burden of proving that racial classifications ‘are narrowly tailored measures that further compelling governmental interests.’ ” Johnson, 125 S.Ct. at 1146 (quoting Adarand, 515 U.S. at 227, 115 S.Ct. 2097). As noted above, the Supreme Court has explained that we “ ‘apply strict scrutiny to all racial classifications to “smoke out” illegitimate uses of race by assuring that government is pursuing a goal important enough to warrant use of a highly suspect tool.’ ” Id. (quoting Croson, 488 U.S. at 493, 109 S.Ct. 706 (plurality opinion)) (emphasis in Johnson; alteration incorporated).', 'mbe_2643', 0, '41'),
('mbe_390', 'mbe', '390', '221', 'MBE-1978-83-part5', '', '42', 'All lawyers practicing in the state of Erewhon must be members of the State Bar Association, by order of the state supreme court. Several state officials serve on the Bar Association''s Board of Bar Governors. The Board of Bar Governors authorizes the payment of dues for two staff members to the Cosmopolitan Club, a private dining club licensed to sell alcohol beverages. The Cosmopolitan Club is frequented by affluent businessmen and professionals and by legislators. It is generally known that the purpose of the membership of the Bar Association staff is to enable them to go where members of the "elite" meet and to lobby for legislation in which the Bar Association is interested. The State Bar Association has numerous committees and subcommittees concerned with family law, real estate law, unauthorized practice, etc., and its recommendations often influence state policy. Some committee meetings are held at the Cosmopolitan Club. The club is known to have rules which restrict membership by race, religion, and sex. Plaintiffs, husband and wife, who are members of the Erewhon Bar Association, petition the Board of Bar Governors to adopt a resolution prohibiting the payment of club dues to and the holding of meetings of the Bar Association or its committees at places which discriminate on the basis of race, religion, or sex. After substantial public discussion, the Board of Bar Governors, by a close vote, fails to pass such a resolution. These events receive extensive coverage in the local newspapers. Plaintiffs bring an action in federal court seeking an injunction against such payments and the holding of meetings in such places as the Cosmopolitan Club.', 'Which of the following actions should a federal district court take with respect to jurisdiction?', 'Hear the case on the merits, because a federal claim is presented.', 'Hear the case on the merits, because the expenditure of state funds in support of segregation is forbidden by the Fifth Amendment.', 'Abstain from jurisdiction, because the constitutional issue should be litigated first in a state court.', 'Dismiss the case for lack of jurisdiction, because the issue of Bar Association activities is solely within the domain of state law.', 'A', '“[F]ederal jurisdiction demands not only a contested federal issue, *1010 but a substantial one, indicating a serious federal interest in claiming the advantages thought to be inherent in a federal forum.” Singh, 538 F.3d at 338.', 'mbe_2644', 0, '42'),
('mbe_410', 'mbe', '410', '233', 'MBE-1978-83-part6', '', '10', '', 'In a telephone call on March 1, Adams, an unemployed, retired person, said to Daws, "I will sell my automobile for $3,000 cash. I will hold this offer open through March 14." On March 12, Adams called Dawes and told her that he had sold the automobile to Clark. Adams in fact had not sold the automobile to anyone. On March 14, Dawes learned that Adams still owned the automobile, and on that date called Adams and said, "I''m coming over to your place with $3,000." Adams replied, "Don''t bother. I won''t deliver the automobile to you under any circumstances." Dawes protested, but made no further attempt to pay for or take delivery of the automobile. In an action by Dawes against Adams for breach of contract, Dawes probably will', 'succeed, because Adams had assured her that the offer would remain open through March 14', 'succeed, because Adams had not in fact sold the automobile to Clark', 'not succeed, because Dawes had not tendered the $3,000 to Adams on or before March 14', 'not succeed, because on March 12 Adams had told Dawes that he had sold the automobile to Clark', 'D', 'To properly plead breach of contract, “[t]he complaint must identify the specific provision of the contract allegedly breached by the defendant.” Donohue v. Apple, Inc., 871 F.Supp.2d 913, 930 (N.D.Cal.2012) (citing Progressive West Ins. Co. v. Super. Ct., 135 Cal.App.4th 263, 281, 37 Cal.Rptr.3d 434 (2005)).', 'mbe_2645', 0, '10'),
('mbe_417', 'mbe', '417', '239', 'MBE-1978-83-part6', '', '17', '', 'Carver is a chemical engineer. She has no interest in or connection with Chemco. Carver noticed that Chemco''s most recent publicly issued financial statement listed, as part of Chemco''s assets, a large inventory of a certain special chemical compound. This asset was listed at a cost of $100,000, but Carver knew that the ingredients of the compound were in short supply and that the current market value of the inventory was in excess of $1,000,000. There was no current public quotation of the price of Chemco stock. The book value of Chemco stock, according to the statement, was $5 a share; its actual value was $30 a share. Knowing these facts, Carver offered to purchase from Page at $6 a share the 1,000 shares of Chemco stock owned by Page. Page and Carver had not previously met. Page sold the stock to Carver for $6 a share. If Page asserts a claim based on misrepresentation against Carver, will Page prevail''?', 'Yes, because Carver knew that the value of the stock was greater than the price she offered.', 'Yes, if Carver did not inform Page of the true value of the inventory.', 'No, unless Carver told Page that the stock was not worth more than $6 a share.', 'No, if Chemco''s financial statement was available to Page.', 'C', 'The elements of fraudulent misrepresentation are: 1) a false material representation; 2) the speaker''s knowledge of the falsity of the misrepresentation or ignorance of the truth; 3) the speaker''s intent that the hearer act upon the misrepresentation in a manner reasonably contemplated; 4) the hearer''s ignorance of the falsity of the misrepresentation; 5) the hearer''s reliance on its truth; 6) the hearer''s right to rely thereon; and 7) the hearer''s consequent and proximately caused damages. Id. at 489–90; Roth v. Equitable Life Assurance Society, 210 S.W.3d 253, 258 (Mo.App. E.D.2006); Urologic Surgeons, Inc. v. Bullock, 117 S.W.3d 722, 725–26 (Mo.App. E.D.2003). If a plaintiff fails to establish any one of these elements, his claim also will fail. Mprove, 135 S.W.3d at 490.', 'mbe_2646', 0, '17'),
('mbe_467', 'mbe', '467', '282', 'MBE-1985-part7', '', '15', 'Adams, Bennett, and Curtis are charged in a common law jurisdiction with conspiracy to commit larceny. The state introduced evidence that they agreed to go to Nelson''s house to take stock certificates from a safe in Nelson''s bedroom, that they went to the house, and that they were arrested as they entered Nelson''s bedroom. Adams testified that he thought the stock certificates belonged to Curtis, that Nelson was improperly keeping them from Curtis, and that he went along to aid in retrieving Curtis'' property. Bennett testified that he suspected Adams and Curtis of being thieves and joined up with them in order to catch them. He also testified that he made an anonymous telephone call to the police alerting them to the crime and that the call caused the police to be waiting for them when they walked into Nelson''s bedroom. Curtis did not testify.', 'If the jury believes Adams, it should find him', 'guilty, because there was an agreement and the entry into the bedroom is sufficient for the overt act', 'guilty, because good motives are not a defense to criminal liability', 'not guilty, because he did not have a corrupt motive', 'not guilty, because he did not intend to steal', 'D', '“(g) If the definition of a crime prescribes a culpable mental state with regard to a particular element or elements of that crime, the prescribed culpable mental state shall be required only as to specified element or elements, and a culpable mental state shall not be required as to any other element of the crime unless otherwise provided.
“(h) A person acts ‘intentionally,’ or ‘with intent,’ with respect to the nature of such person''s conduct or to a result of such person''s conduct when it is such person''s conscious objective or desire to engage in the conduct or cause the result. All crimes defined in this code in which the mental culpability requirement is expressed as ‘intentionally’ or ‘with intent’ are specific intent crimes. A crime may provide that any other culpability requirement is a specific intent.', 'mbe_2647', 0, '15'),
('mbe_468', 'mbe', '468', '282', 'MBE-1985-part7', '', '16', 'Adams, Bennett, and Curtis are charged in a common law jurisdiction with conspiracy to commit larceny. The state introduced evidence that they agreed to go to Nelson''s house to take stock certificates from a safe in Nelson''s bedroom, that they went to the house, and that they were arrested as they entered Nelson''s bedroom. Adams testified that he thought the stock certificates belonged to Curtis, that Nelson was improperly keeping them from Curtis, and that he went along to aid in retrieving Curtis'' property. Bennett testified that he suspected Adams and Curtis of being thieves and joined up with them in order to catch them. He also testified that he made an anonymous telephone call to the police alerting them to the crime and that the call caused the police to be waiting for them when they walked into Nelson''s bedroom. Curtis did not testify.', 'If the jury believes Bennett, it should find him', 'guilty, because there was an agreement and the entry into the bedroom is sufficient for the overt act', 'guilty, because he is not a police officer and thus cannot claim any privilege of apprehending criminals', 'not guilty, because he did not intend to steal', 'not guilty, because he prevented the theft from occurring', 'C', 'Mens rea is an essential element of a crime. See Ward v. State, 271 Ga. 648, 653, 520 S.E.2d 205 (1999); Bacon v. State, 209 Ga. 261, 263, 71 S.E.2d 615 (1952). Thus, the commission of a crime requires “a joint operation of an act or omission to act [or actus reus] and intention or criminal negligence [or mens rea].” OCGA § 16–2–1(a).', 'mbe_2648', 0, '16'),
('mbe_469', 'mbe', '469', '282', 'MBE-1985-part7', '', '17', 'Adams, Bennett, and Curtis are charged in a common law jurisdiction with conspiracy to commit larceny. The state introduced evidence that they agreed to go to Nelson''s house to take stock certificates from a safe in Nelson''s bedroom, that they went to the house, and that they were arrested as they entered Nelson''s bedroom. Adams testified that he thought the stock certificates belonged to Curtis, that Nelson was improperly keeping them from Curtis, and that he went along to aid in retrieving Curtis'' property. Bennett testified that he suspected Adams and Curtis of being thieves and joined up with them in order to catch them. He also testified that he made an anonymous telephone call to the police alerting them to the crime and that the call caused the police to be waiting for them when they walked into Nelson''s bedroom. Curtis did not testify.', 'If the jury believes both Adams and Bennett, it should find Curtis', 'guilty, because there was an agreement and the entry into the bedroom is sufficient for the overt act', 'guilty, because he intended to steal', 'not guilty, because a conviction would penalize him for exercising his right not to be a witness', 'not guilty, because Adams and Bennett did not intend to steal', 'D', 'A criminal conspiracy is an agreement between two or more persons to accomplish an unlawful purpose. United States v. Dellosantos, 649 F.3d 109, 115 (1st Cir. 2011). To convict defendant of conspiracy in violation of 21 U.S.C. § 846, the government was required to prove that “(1) a conspiracy existed, (2) the defendant had knowledge of the conspiracy, and (3) the defendant knowingly and voluntarily participated in the conspiracy. Under the third element, the evidence must establish that the defendant both intended to join the conspiracy and intended to effectuate the objects of the conspiracy.” Id.', 'mbe_2649', 0, '17'),
('mbe_486', 'mbe', '486', '296', 'MBE-1985-part7', '', '34', '', 'Which of the following is most likely to be found to be a strict liability offense?', 'A city ordinance providing for a fine of not more than $200 for shoplifting', 'A federal statute making it a felony to possess heroin', 'A state statute making it a felony to fail to register a firearm', 'A state statute making the sale of adulterated milk a misdemeanor', 'D', 'Every crime has a set of elements that the prosecuting attorney must prove in order to establish the defendant''s guilt. One of these elements typically has to do with the defendant''s mental state. Usually, prosecutors must show that the defendant acted intentionally or knowingly. But, with strict liability crimes, the prosecution doesn''t need to prove that a defendant intended to do something that''s illegal. The prosecution doesn''t even need to establish that the defendant was reckless or negligent. It''s enough for a conviction to prove that the act was committed and the defendant committed it.

Why Have Strict Liability Crimes?
"Strict liability" is a concept mainly applicable to civil law. It''s a way of holding someone accountable for behavior regardless of fault (such as in product liability cases). Because criminal punishment is usually reserved for those who act with a culpable (guilty) mental state, strict liability crimes are rare. But some acts produce outcomes that lawmakers want to criminally punish regardless of a defendant''s state of mind.

What Are Common Strict Liability Offenses?
Probably the most well-known example of a strict liability crime is statutory rape. Most states make it a crime to have sex with a minor, even if the defendant honestly and reasonably believed that the sexual partner was old enough to give legal consent.

Selling alcohol to a minor is another strict liability crime. In some states, a conviction is appropriate even if the seller honestly thought the buyer was 21 or older and tried to confirm as much.

Some traffic offenses are strict liability crimes. In many places, it doesn''t matter whether a driver knowingly went over the speed limit—the plain act of speeding typically justifies a conviction.', 'mbe_2650', 0, '34'),
('mbe_488', 'mbe', '488', '298', 'MBE-1985-part7', '', '36', '', 'When Mary Weld visited Dugan''s Alleys to participate in the weekly bowling league competition held there, she brought her 2-year-old son, Bobby, along and left him in a nursery provided by Dugan for the convenience of his customers. The children in the nursery were normally supervised by three attendants, but at this particular time, as Mary Weld knew, there was only one attendant present to care for about twenty children of assorted ages. About thirty minutes later, while the attendant was looking the other way, Bobby suddenly started to cry. The attendant found him lying on his back, picked him up, and called his mother. It was later discovered that Bobby had suffered a skull fracture. If a claim is asserted against Dugan on Bobby''s behalf, will Bobby prevail?', 'Yes, because Dugan owed the child the highest degree of care.', 'Yes, because a 2 year old is incapable of contributory negligence.', 'No, unless Dugan or his employees failed to exercise reasonable care to assure Bobby''s safety.', 'No, if Mary Weld assumed the risk by leaving Bobby in the nursery.', 'C', 'Such relationships (those that impose a duty of care) may arise by operation of law (e.g. master-servant), by agreement, or may be imposed by law in particular fact circumstances. Each of these relationships involves the essential determination as a matter of policy that the claimed supervisor has some duty of care either to protect the one to be supervised from injury or to protect third persons from injuries caused by the one to be supervised. In some instances, as with children, the duty may be to protect the supervised individual from self-imposed injury. E.g., Rogger v. Voyles, 797 S.W.2d 844, 846 (Mo.App.1990)(13 year-old child drove automobile and lost control). In other instances, the duty may be to protect against harm to the child by instrumentalities or conditions of land or personal property. See Smith v. Archbishop of St. Louis, 632 S.W.2d 516, 518–19 (Mo.App.1982)(child injured when costume set afire by burning candle on teacher''s desk). Finally the duty may be to protect the child under supervision against harm by third persons (whether negligent or intentional).  In each of these situations involving children, policy and decisional law has established that “acceptance of the custody and control of a minor child creates a relationship sufficient to support a duty of care.” A.R.H. v. W.H.S., 876 S.W.2d 687, 691 (Mo.App.1994). The duty imposed is to supervise the minor child. Id. at 689. Proof of the necessary predicate relationship, therefore, establishes the first element of a cause of action in negligence—the existence of a duty of care.', 'mbe_2651', 0, '36'),
('mbe_513', 'mbe', '513', '321', 'MBE-1989-90-part2', '', '10', 'When Denton heard that his neighbor, Prout, intended to sell his home to a minority purchaser, Denton told Prout that Prout and his wife and children would meet with "accidents" if he did so. Prout then called the prospective purchaser and told him that he was taking the house off the market.', 'If Prout asserts a claim against Denton for assault, Prout will', 'recover if Denton intended to place Prout in fear of physical harm', 'recover because Denton''s conduct was extreme and outrageous', 'not recover if Denton took no action that threatened immediate physical harm to Prout', 'not recover because Prout''s action removed any threat of harmful force', 'C', 'An “assault” is an attempt or offer, with force or violence, to inflict bodily harm on another or engage in some offensive conduct. In re McGee, 278 S.C. 506, 507, 299 S.E.2d 334, 334 (1983); Gathers v. Harris Teeter Supermarket, Inc., 282 S.C. 220, 230, 317 S.E.2d 748, 754–755 (Ct.App.1984) ( “[A]n assault occurs when a person has been placed in reasonable fear of bodily harm by the conduct of the defendant.”).  The elements of assault are: (1) conduct of the defendant which places the plaintiff, (2) in reasonable fear of bodily harm. Herring v. Lawrence Warehouse Co., 222 S.C. 226, 241, 72 S.E.2d 453, 458 (1952); Jones by Robinson v. Winn–Dixie Greenville, Inc., 318 S.C. 171, 175, 456 S.E.2d 429, 432 (Ct.App.1995).', 'mbe_2652', 0, '10'),
('mbe_514', 'mbe', '514', '321', 'MBE-1989-90-part2', '', '11', 'When Denton heard that his neighbor, Prout, intended to sell his home to a minority purchaser, Denton told Prout that Prout and his wife and children would meet with "accidents" if he did so. Prout then called the prospective purchaser and told him that he was taking the house off the market.', 'If Prout asserts a claim against Denton for intentional infliction of emotional distress, Prout will', 'recover if Prout suffered severe emotional distress as a consequence of Denton''s conduct', 'recover because Denton intended to frighten Prout', 'not recover because Denton made no threat of immediate physical harm to Prout or his family', 'not recover if Prout suffered no physical harm as a consequence of Denton''s conduct', 'A', 'To prove a claim for the intentional infliction of emotional distress, a plaintiff must establish the following elements: “that the defendant''s conduct was (1) intentional or reckless, (2) so outrageous that it is not tolerated by civilized society, and (3) resulted in serious mental injury to the plaintiff.” Rogers v. Louisville Land Co., 367 S.W.3d 196, 205 (Tenn.2012). This Court has observed that, “A plaintiff''s burden to demonstrate outrageous conduct ‘is not an easy burden to meet.’ ” Brown, 393 S.W.3d at 703 (quoting Weaver v. Pardue, No. M2010–00124–COA–R3–CV, 2010 WL 4272687, at *5 (Tenn.Ct.App. Oct. 28, 2010)) (further citation omitted).', 'mbe_2653', 0, '11')
